create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key default gen_random_uuid(),name text not null,journey text not null check(journey in('aspiring','opening','operating')),created_at timestamptz not null default now());
create table if not exists profiles(id uuid primary key,organization_id uuid not null references organizations(id) on delete cascade,full_name text,role text not null default 'owner',created_at timestamptz not null default now());
create table if not exists restaurants(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,concept text,status text not null default 'planning',created_at timestamptz not null default now());
create table if not exists locations(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id) on delete cascade,name text not null,city text,region text,timezone text not null default 'America/Chicago',created_at timestamptz not null default now());
create table if not exists venture_rooms(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id) on delete cascade,vision jsonb not null default '{}',market_model jsonb not null default '{}',facility_paths jsonb not null default '[]',funding_room jsonb not null default '{}',experience_standard jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists venture_tasks(id uuid primary key default gen_random_uuid(),venture_room_id uuid not null references venture_rooms(id) on delete cascade,workstream text not null,title text not null,status text not null default 'queued',owner text,due_at timestamptz,evidence jsonb not null default '{}');
create table if not exists property_candidates(id uuid primary key default gen_random_uuid(),venture_room_id uuid not null references venture_rooms(id) on delete cascade,provider text,external_id text,candidate_type text not null,address text,asking_cost numeric,raw_data jsonb not null default '{}',score jsonb not null default '{}',status text not null default 'research');
create table if not exists integrations(id uuid primary key default gen_random_uuid(),location_id uuid not null references locations(id) on delete cascade,provider text not null,status text not null default 'pending',scopes text[] not null default '{}',last_synced_at timestamptz,metadata jsonb not null default '{}',unique(location_id,provider));
create table if not exists profit_actions(id uuid primary key default gen_random_uuid(),location_id uuid not null references locations(id) on delete cascade,category text not null,title text not null,evidence jsonb not null default '{}',predicted_impact_cents integer not null default 0,confidence numeric not null default 0,risk text not null default 'medium',status text not null default 'pending',created_at timestamptz not null default now());
create table if not exists guest_experiences(id uuid primary key default gen_random_uuid(),location_id uuid not null references locations(id) on delete cascade,guest_key_hash text,quoted_wait_minutes integer,actual_wait_minutes integer,feedback_score integer check(feedback_score between 1 and 5),recovery jsonb not null default '{}',created_at timestamptz not null default now());
